<div class="panel table-scroll"><table><thead><tr><th>Code / purpose</th><th>Discount / scope</th><th>Status / dates</th><th>Usage</th><th>Actions</th></tr></thead><tbody><?php foreach($codes as $c):$status=promo_status($c);if(!empty($_GET['status'])&&$_GET['status']!==$status||!empty($_GET['type'])&&$_GET['type']!==$c['discount_type']||!empty($_GET['kind'])&&$_GET['kind']!==$c['kind']||!empty($_GET['expires'])&&(!$c['ends_at']||substr($date($c['ends_at']),0,10)>$_GET['expires']))continue;$shown++;$uses=promo_counts($c['id']); ?><tr><td><strong class="promo-code-label"><?= e($c['code']) ?></strong><small><?= e($c['name']) ?> · <?= $c['kind']==='welcome'?'Automatic email welcome':'Manual campaign' ?></small></td><td><?= $c['discount_type']==='free_shipping'?'Free shipping':($c['discount_type']==='percentage'?(int)$c['discount_value'].'%':e($c['currency']).' '.number_format($c['discount_value']/100,2)) ?><small><?= e($c['scope']) ?> · No stacking</small><small>Minimum <?= e($c['currency']) ?> <?= number_format($c['minimum_amount']/100,2) ?></small></td><td><span class="status-tag"><?= e($status) ?></span><small>Starts <?= e(welcome_expiry_label($c['starts_at'])) ?></small><small><?= $c['ends_at']?'Expires '.e(welcome_expiry_label($c['ends_at'])):'No expiry' ?></small></td><td><?= (int)$uses['redeemed'] ?> successful<small><?= (int)$uses['reserved'] ?> pending reservations<?= $uses['legacy']?' · '.(int)$uses['legacy'].' legacy redeemed':'' ?></small><small><?= $c['total_limit']?max(0,(int)$c['total_limit']-$uses['held']).' uses remaining':'Unlimited total uses' ?> · Per email <?= $c['email_limit']?(int)$c['email_limit']:'unlimited' ?></small></td><td><div class="table-actions"><a class="text-link" href="/admin/offers?tab=codes&amp;edit=<?= e($c['id']) ?>"><?= $c['kind']==='welcome'||$c['archived']?'View':'Edit' ?></a><?php if(!$c['archived']): $actions=['disable'=>'Disable','archive'=>'Archive'];if($c['kind']==='manual'&&!$c['active'])$actions=['enable'=>'Enable',...$actions];if($c['kind']==='manual'&&!$uses['held'])$actions['delete']='Delete / archive';foreach($actions as $action=>$label): ?><form method="post" action="/admin/offers" <?= in_array($action,['archive','delete'],true)?'data-confirm="Remove this code from future use? Existing order history will be preserved."':'' ?>><?= csrf_field() ?><input type="hidden" name="section" value="offers"><input type="hidden" name="promo_admin" value="1"><input type="hidden" name="action" value="<?= $action ?>"><input type="hidden" name="id" value="<?= e($c['id']) ?>"><button class="text-button <?= $action==='delete'?'danger':'' ?>"><?= $label ?></button></form><?php endforeach;endif ?></div></td></tr><?php endforeach ?></tbody></table><?php if(!$shown): ?><p>No codes match these filters.</p><?php endif ?></div>
